  id INTEGER PRIMARY KEY,
  account_number TEXT UNIQUE NOT NULL,
  balance REAL CHECK (balance >= 0.00),
  status TEXT CHECK (status IN ('ACTIVE', 'FROZEN', 'CLOSED'))
);

